"""A tiny spreadsheet formula engine.

``evaluate(cells)`` resolves every cell to a ``float``, following references
(including forward and transitive ones) and raising :class:`CycleError` when
the reference graph contains a cycle.
"""

import re

__all__ = ["evaluate", "CycleError"]


class CycleError(Exception):
    """Raised when a cell depends on itself, directly or transitively."""


# A cell's value is either a bare number or a formula starting with "=".
# Formulas are compiled to a small AST built from tuples:
#
#   ("num", value)            literal
#   ("ref", name)             reference to another cell
#   ("neg", operand)          unary minus
#   ("bin", op, left, right)  binary + - * /
_NUM = "num"
_REF = "ref"
_NEG = "neg"
_BIN = "bin"

_OPS = "+-*/"

# Tokens are (kind, text) pairs; for numbers the text is the float value.
_TOKEN_RE = re.compile(
    r"""(?P<space>\s+)
      | (?P<num>\d+(?:\.\d*)?|\.\d+)
      | (?P<ref>[A-Za-z]+[0-9]*)
      | (?P<op>[+\-*/()])
    """,
    re.VERBOSE,
)


def _tokenize(source, cell):
    """Split ``source`` (a formula body, without the leading "=") into tokens."""
    tokens = []
    pos = 0
    while pos < len(source):
        match = _TOKEN_RE.match(source, pos)
        if match is None:
            raise ValueError(
                f"invalid formula in cell {cell!r}: unexpected character "
                f"{source[pos]!r} at position {pos}"
            )
        pos = match.end()
        kind = match.lastgroup
        if kind == "space":
            continue
        text = match.group()
        if kind == "num":
            tokens.append((_NUM, float(text)))
        else:
            tokens.append((kind, text))
    return tokens


class _Parser:
    """Recursive-descent parser for the formula grammar.

    expr    := term (("+" | "-") term)*
    term    := factor (("*" | "/") factor)*
    factor  := ("-" | "+") factor | primary
    primary := NUMBER | REF | "(" expr ")"
    """

    def __init__(self, source, cell):
        self._cell = cell
        self._source = source
        self._tokens = _tokenize(source, cell)
        self._pos = 0

    def parse(self):
        if not self._tokens:
            raise ValueError(f"invalid formula in cell {self._cell!r}: empty formula")
        node = self._expr()
        if self._pos != len(self._tokens):
            raise ValueError(
                f"invalid formula in cell {self._cell!r}: "
                f"unexpected {self._tokens[self._pos][1]!r}"
            )
        return node

    def _peek(self):
        if self._pos < len(self._tokens):
            return self._tokens[self._pos]
        return (None, None)

    def _take(self):
        token = self._peek()
        self._pos += 1
        return token

    def _match_op(self, *ops):
        """Consume and return the next token if it is one of ``ops``."""
        kind, text = self._peek()
        if kind == "op" and text in ops:
            self._pos += 1
            return text
        return None

    def _expr(self):
        node = self._term()
        while True:
            op = self._match_op("+", "-")
            if op is None:
                return node
            node = (_BIN, op, node, self._term())

    def _term(self):
        node = self._factor()
        while True:
            op = self._match_op("*", "/")
            if op is None:
                return node
            node = (_BIN, op, node, self._factor())

    def _factor(self):
        if self._match_op("-") is not None:
            return (_NEG, self._factor())
        if self._match_op("+") is not None:
            return self._factor()
        return self._primary()

    def _primary(self):
        kind, text = self._take()
        if kind == _NUM:
            return (_NUM, text)
        if kind == "ref":
            return (_REF, text)
        if kind == "op" and text == "(":
            node = self._expr()
            if self._match_op(")") is None:
                raise ValueError(
                    f"invalid formula in cell {self._cell!r}: missing ')'"
                )
            return node
        shown = "end of formula" if kind is None else repr(text)
        raise ValueError(
            f"invalid formula in cell {self._cell!r}: expected a number, "
            f"cell reference or '(' but found {shown}"
        )


def _compile(name, value):
    """Turn a raw cell value into an AST."""
    if not isinstance(value, str):
        return (_NUM, float(value))
    text = value.strip()
    if text.startswith("="):
        return _Parser(text[1:], name).parse()
    try:
        return (_NUM, float(text))
    except ValueError:
        raise ValueError(
            f"invalid value in cell {name!r}: {value!r} is neither a number "
            f"nor a formula starting with '='"
        ) from None


def _dependencies(node, out):
    """Append every cell referenced by ``node`` to ``out``, left to right."""
    kind = node[0]
    if kind == _REF:
        out.append(node[1])
    elif kind == _NEG:
        _dependencies(node[1], out)
    elif kind == _BIN:
        _dependencies(node[2], out)
        _dependencies(node[3], out)


def _compute(node, values):
    kind = node[0]
    if kind == _NUM:
        return node[1]
    if kind == _REF:
        return values[node[1]]
    if kind == _NEG:
        return -_compute(node[1], values)
    op = node[1]
    left = _compute(node[2], values)
    right = _compute(node[3], values)
    if op == "+":
        return left + right
    if op == "-":
        return left - right
    if op == "*":
        return left * right
    return left / right


def _resolve(root, compiled, values):
    """Depth-first resolve of ``root`` and everything it depends on.

    Iterative rather than recursive so that long reference chains do not
    overflow the interpreter stack. ``values`` doubles as the memo table;
    cells on the current path live in ``pending`` and close the cycle.
    """
    pending = set()
    stack = [[root, iter(_dependencies(compiled[root], []))]]
    pending.add(root)
    while stack:
        name, deps = stack[-1]
        dep = next(deps, None)
        while dep is not None and dep in values:
            dep = next(deps, None)
        if dep is None:
            # Every dependency is resolved, so this cell can be computed.
            stack.pop()
            pending.discard(name)
            values[name] = _compute(compiled[name], values)
            continue
        if dep not in compiled:
            raise KeyError(f"cell {name!r} references undefined cell {dep!r}")
        if dep in pending:
            path = [frame[0] for frame in stack]
            cycle = path[path.index(dep):] + [dep]
            raise CycleError(" -> ".join(cycle))
        pending.add(dep)
        stack.append([dep, iter(_dependencies(compiled[dep], []))])


def evaluate(cells):
    """Compute the ``float`` value of every cell in ``cells``.

    References may point forward or form transitive chains. Raises
    :class:`CycleError` if any cell depends on itself, and ``ValueError`` for
    values that are neither numbers nor valid formulas.
    """
    compiled = {name: _compile(name, value) for name, value in cells.items()}
    values = {}
    for name in compiled:
        if name not in values:
            _resolve(name, compiled, values)
    # Report in the caller's order rather than dependency order.
    return {name: values[name] for name in compiled}

